messages.content:
Tool response:
Tool: update_user_primary_insurance
Description: Update User Primary Insurance
Parameters:
    {
      "type": "object",
      "properties": {
        "user_id": {
          "type": "integer",
          "description": "Internal ID of the user whose primary insurance is being updated",
          "title": "User Id"
        },
        "insurance_provider_name": {
          "type": "string",
          "title": "Insurance Provider Name",
          "description": "Name of the insurance provider (e.g., 'Blue Cross Blue Shield')"
        },
        "member_id": {
          "type": "string",
          "title": "Member Id",
          "description": "Member ID for the insurance policy"
        },
        "group_number": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Group Number",
          "description": "Group number associated with the insurance policy"
        },
        "policyholder_name": {
          "type": "string",
          "title": "Policyholder Name",
          "description": "Full name of the policyholder"
        }
      },
      "required": [
        "user_id"
      ]
    }
